:'.($r['reasonCode']??'')){'ready:','already_applied:'=>is_int($legacy)&&is_int($local),'skipped:OBJECT_NOT_IMPORTED','skipped:LEGACY_ENGINEER_MISSING'=>is_null($legacy)&&is_null($local),'skipped:LEGACY_USER_NOT_FOUND','skipped:LEGACY_USER_INACTIVE','skipped:IDENTITY_LINK_MISSING','conflict:IDENTITY_LINK_AMBIGUOUS'=>is_int($legacy)&&is_null($local),'skipped:LOCAL_ENGINEER_INELIGIBLE'=>is_int($legacy)&&is_int($local),'conflict:CURRENT_ASSIGNMENT_DIFFERS'=>is_int($legacy),'conflict:SOURCE_CORRUPT'=>is_null($legacy)&&is_null($local)||is_int($legacy),default=>false};if(!$idsOk)fail('INVALID_PREVIEW',64);$key=$r['status']==='already_applied'?'alreadyApplied':$r['status'];$actual[$key]++;$last=$r['objectId'];}if($actual!==$d['counts'])fail('INVALID_PREVIEW',64);$without=$d;unset($without['digest']);$canonical=json_encode($without,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);if(!hash_equals(hash('sha256',$canonical),$d['digest'])||!hash_equals($expected,$d['digest'])||$raw!==json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR))fail('INVALID_PREVIEW',64);return$d;}
try{$args=array_slice($argv,1);$mode=array_shift($args);if(!in_array($mode,['preview','apply','reconcile'],true))fail('INVALID_ARGUMENTS',64);$opt=[];foreach($args as$a){if($a==='--all-imported'){$opt['all'][]=true;continue;}if(!str_starts_with($a,'--')||!str_contains($a,'='))fail('INVALID_ARGUMENTS',64);[$k,$v]=explode('=',substr($a,2),2);$opt[$k][]=$v;}$op=$opt['operation-id'][0]??'';if(!uuid($op))fail('INVALID_ARGUMENTS',64);$process=px('FMONITOR_PROCESS_TABLE_PREFIX');$legacy=px('FMONITOR_LEGACY_TABLE_PREFIX');$doc=null;$actor=null;$now=null;if($mode==='apply'){$path=$opt['preview'][0]??'';$digest=$opt['digest'][0]??'';$bytes=is_file($path)?file_get_contents($path):false;if($bytes===false||preg_match('/^[0-9a-f]{64}$/D',$digest)!==1)fail('INVALID_PREVIEW',64);$doc=previewBytes($bytes,$op,$digest);if(!hash_equals($digest,$doc['digest']))fail('INVALID_PREVIEW',2);$actor=filter_var(ev('FMONITOR_MIGRATION_ACTOR_USER_ID'),FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$now=ev('FMONITOR_MIGRATION_NOW_UTC');if($actor===false||preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/D',$now)!==1)fail('INVALID_ARGUMENTS',64);}$db=new mysqli(ev('FMONITOR_DB_HOST'),ev('FMONITOR_DB_USER'),ev('FMONITOR_DB_PASSWORD'),ev('FMONITOR_DB_NAME'),(int)ev('FMONITOR_DB_PORT'));$db->set_charset('utf8mb4');$owner=new LegacyControlEngineerMigration($db,$process,$legacy);
